mapper.select:
/* CastChknMapper.retrieveAlnCdList */
SELECT DISTINCT A.ALN_CD
FROM GOOWN.TI_GO_CKNCT_DALY_ALOT A
WHERE 1 = 1
AND A.OPER_YMD = #{ymd}
AND A.TMNL_ID = #{tmnlId}
AND A.USE_YN = 'Y'
ORDER BY A.ALN_CD

/* CastChknMapper.retrieveUserChknOperHrList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    NVL(A.OPER_BGNG_HOUR, 0) AS OPER_BGNG_HOUR,
    NVL(A.OPER_END_HOUR, 0) AS OPER_END_HOUR
FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR A
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}
AND A.TMNL_ID = #{tmnlId}
ORDER BY A.CHKN_ISL_CD, A.OPER_HR_SN

mapper.delete:
/* CastChknMapper.deleteUserChknIslandList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

/* CastChknMapper.deleteUserChknOperHrList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

/* CastChknMapper.deleteUserChknBoothList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

mapper.insert:
/* CastChknMapper.insertUserChknIslandList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_ISL ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, BOOTH_CNT, KOS_CNT, SBD_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{island.boothCnt}, #{island.kioskCnt}, #{island.bagDropCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastChknMapper.insertUserChknOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, OPER_HR_SN, OPER_BGNG_HOUR, OPER_END_HOUR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{oprTimeIdx} + 1, #{oprTime.operBgngHour}, #{oprTime.operEndHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastChknMapper.insertUserChknBoothList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, BOOTH_NO, ALN_CD, CSTM_ALTMNT_YN, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{booth.boothNo}, #{booth.alnCd}, #{booth.cstmAltmntYn}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
